     1	// Renders an uncaught Python exception the way CPython prints it to stderr, so
     2	// the failure modes of the port look like the failure modes of the original.
     3	//
     4	// Two details of the reference build are reproduced here:
     5	//
     6	//  * CPython resolves source lines through linecache at traceback time, so the
     7	//    offending statement and its caret line only appear when a file named
     8	//    test14.py is readable from the working directory. Run the reference binary
     9	//    from a directory without it and those two lines vanish.
    10	//  * The caret span comes from column offsets baked into the compiled code
    11	//    object, not from re-parsing the line, so it stays fixed at the
    12	//    `base58.b58decode_int(args.c)` sub-expression.
    13	//
    14	// The frozen build also emits a PyInstaller bootloader line whose embedded
    15	// process id changes every run; that is a launcher artifact rather than part of
    16	// the Python program, so it is not reproduced. stdout stays empty either way and
    17	// the exit status is 1 in both.
    18	
    19	import { readFileSync } from 'node:fs';
    20	
    21	const SOURCE_FILE = 'test14.py';
    22	const TRACEBACK_INDENT = '    ';
    23	
    24	/** Read one 1-indexed line of a source file, or null if unavailable. */
    25	function lookupLine(fileName, lineNumber) {
    26	  try {
    27	    const lines = readFileSync(fileName, 'utf8').split('\n');
    28	    return lines[lineNumber - 1] ?? null;
    29	  } catch {
    30	    return null;
    31	  }
    32	}
    33	
    34	/** The `^^^^` line CPython draws under the failing sub-expression. */
    35	function caretLine(source, colStart, colEnd) {
    36	  const start = Math.min(colStart, source.length);
    37	  const end = Math.min(colEnd, source.length);
    38	  if (end <= start) return null;
    39	  return ' '.repeat(start) + '^'.repeat(end - start);
    40	}
    41	
    42	/**
    43	 * @param {{pyType: string, pyMessage: string, pyFrames?: string[]}} error
    44	 * @param {{line: number, colStart: number, colEnd: number}} callSite
    45	 */
    46	export function formatTraceback(error, callSite) {
    47	  let out = 'Traceback (most recent call last):\n';
    48	  out += `  File "${SOURCE_FILE}", line ${callSite.line}, in <module>\n`;
    49	
    50	  const raw = lookupLine(SOURCE_FILE, callSite.line);
    51	  if (raw !== null) {
    52	    const source = raw.trim();
    53	    out += `${TRACEBACK_INDENT}${source}\n`;
    54	    const carets = caretLine(source, callSite.colStart, callSite.colEnd);
